UPDATE `message` SET `spam_verdict` = json_set(`spam_verdict`, '$.decidedBy', CASE WHEN json_extract(`spam_verdict`, '$.modelOutcome') = 'Answered' THEN 'Model' WHEN EXISTS (SELECT 1 FROM json_each(`spam_verdict`, '$.reasons') WHERE json_extract(`value`, '$.symbol') <> json_extract(`value`, '$.name')) THEN 'Rspamd' ELSE 'Inline' END) WHERE json_extract(`spam_verdict`, '$.state') = 'Checked';
